css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.lt512-widget {
  --lt512-metal: #D7D8DB;
  --lt512-outline: #4E4E4E;
  --lt512-liquid: #A0CFE9;
  --lt512-valve: #0E0E55;
  --lt512-control: #01524F;
  --lt512-text: #000000;

  display: grid;
  place-items: center;

  width: 100%;
  height: 100%;

  overflow: hidden;
  background: transparent;

  font-family: "Segoe UI", Arial, sans-serif;
  pointer-events: none;
}

.lt512-svg {
  display: block;
  width: 100%;
  height: 100%;

  overflow: hidden;
  background: transparent;

  shape-rendering: geometricPrecision;
}

/* Gradientes */

.lt512-metal-stop {
  stop-color: var(--lt512-metal);
}

.lt512-liquid-stop {
  stop-color: var(--lt512-liquid);
}

/* Tanques y equipos */

.lt512-tank {
  filter: url("#lt512-equipment-shadow");
}

.lt512-tank-body {
  fill: url("#lt512-metal-gradient");

  stroke: var(--lt512-outline);
  stroke-width: 1.8px;
  stroke-linejoin: round;
}

.lt512-liquid {
  fill: url("#lt512-liquid-gradient");
  stroke: none;
}

.lt512-metal {
  fill: url("#lt512-metal-gradient");

  stroke: var(--lt512-outline);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

.lt512-metal-top {
  fill: url("#lt512-top-gradient");

  stroke: var(--lt512-outline);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

.lt512-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.8px;
  stroke-linecap: round;
  opacity: 0.55;
}

.lt512-detail {
  fill: none;
  stroke: var(--lt512-outline);
  stroke-width: 0.9px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Tuberías de proceso */

.lt512-pipe {
  fill: none;

  stroke: var(--lt512-outline);
  stroke-width: 1.2px;
  stroke-linecap: butt;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.lt512-internal-pipe {
  fill: none;

  stroke: var(--lt512-outline);
  stroke-width: 1.3px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.lt512-flow-arrow {
  fill: var(--lt512-outline);
  stroke: none;
}

/* Válvulas */

.lt512-valve-body {
  fill: none;

  stroke: var(--lt512-valve);
  stroke-width: 1.4px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.lt512-valve-stem {
  fill: none;
  stroke: var(--lt512-valve);
  stroke-width: 0.7px;
  stroke-linecap: butt;
}

.lt512-valve-actuator {
  fill: var(--lt512-valve);
  stroke: var(--lt512-valve);
  stroke-width: 1px;
}

/* Bombas */

.lt512-pump-body {
  fill: url("#lt512-metal-gradient");

  stroke: var(--lt512-valve);
  stroke-width: 1.4px;
  stroke-linejoin: round;
}

.lt512-pump-detail {
  fill: none;

  stroke: var(--lt512-valve);
  stroke-width: 1px;
  stroke-linecap: round;
}

.lt512-indicator-body {
  fill: #F0F1F3;
  stroke: var(--lt512-outline);
  stroke-width: 1px;
}

.lt512-indicator-half {
  fill: var(--lt512-outline);
  stroke: none;
}

.lt512-block {
  fill: var(--lt512-valve);
  stroke: var(--lt512-valve);
  stroke-width: 1.2px;
}

/* Precalentamiento */

.lt512-heater-frame {
  fill: #727983;
  stroke: var(--lt512-outline);
  stroke-width: 1.6px;
}

.lt512-heater-cell {
  fill: url("#lt512-top-gradient");
  stroke: var(--lt512-outline);
  stroke-width: 0.9px;
}

.lt512-heater-fins {
  fill: url("#lt512-fin-pattern");
  stroke: var(--lt512-outline);
  stroke-width: 0.8px;
}

/* Soportes */

.lt512-support {
  fill: none;
  stroke: var(--lt512-outline);
  stroke-width: 1.5px;
  stroke-linecap: round;
}

.lt512-support-hatching {
  fill: url("#lt512-support-pattern");
  stroke: none;
}

/* Rótulos */

.lt512-label-box {
  fill: url("#lt512-top-gradient");
  stroke: var(--lt512-outline);
  stroke-width: 1px;
}

.lt512-label {
  fill: var(--lt512-text);
  font-size: 13px;
  font-weight: 600;
  text-anchor: middle;
}

.lt512-dpk-label {
  fill: var(--lt512-text);
  font-size: 15px;
  font-weight: 600;
  text-anchor: middle;
}

.lt512-footer {
  fill: var(--lt512-text);
  font-size: 16px;
  font-style: italic;
  font-weight: 500;
  text-anchor: end;
}

